// Package interactive provides TTY-related helpers shared between the cli
// and strategy packages without inducing an import cycle (strategy cannot
// import cli).
package interactive

import (
	"io"
	"os"
	"testing"

	"golang.org/x/term"
)

// CanPromptInteractively reports whether interactive confirmation prompts
// (huh forms, yes/no questions, etc.) can be shown. Returns false in CI,
// agent subprocesses that inherit a TTY but can't respond to prompts,
// and other environments without a controlling TTY.
//
// Precedence (first match wins):
//  1. ENTIRE_FAKE_TTY=1 forces interactive ON (simulate human at terminal).
//     Any other non-empty value forces interactive OFF (simulate no TTY).
//  2. testing.Testing() — when running under `go test`, default to OFF so
//     in-process tests don't hang on developer terminals that happen to have
//     a real /dev/tty. Subprocess tests spawning the real entire binary must
//     set ENTIRE_FAKE_TTY=0 explicitly since the subprocess isn't a test binary.
//  3. Agent sentinels (GEMINI_CLI, COPILOT_CLI, PI_CODING_AGENT,
//     GIT_TERMINAL_PROMPT=0) — vendor-set by agent subprocesses.
//  4. CI=<non-empty-non-false> — de-facto CI convention.
//  5. /dev/tty probe — the real check.
func CanPromptInteractively() bool {
	if v := os.Getenv("ENTIRE_FAKE_TTY"); v != "" {
		return v == "1"
	}
	if testing.Testing() {
		return false
	}

	// Agent subprocesses may inherit the user's TTY but can't respond to
	// interactive prompts. Treat them as non-TTY.
	//   - GEMINI_CLI=1: Gemini CLI shell tool (https://geminicli.com/docs/tools/shell/)
	//   - COPILOT_CLI=1: Copilot CLI hook subprocesses (v0.0.421+)
	//   - PI_CODING_AGENT=true: Pi Coding Agent shell tool
	//   - GIT_TERMINAL_PROMPT=0: caller (CI, Factory AI Droid, etc.) asked
	//     git to stop prompting; respect it from git-hook context too.
	if os.Getenv("GEMINI_CLI") != "" ||
		os.Getenv("COPILOT_CLI") != "" ||
		os.Getenv("PI_CODING_AGENT") != "" ||
		os.Getenv("GIT_TERMINAL_PROMPT") == "0" {
		return false
	}

	// CI=<non-empty> is the de-facto CI-provider convention (GitHub Actions,
	// CircleCI, GitLab, Travis, Buildkite). Self-hosted runners expose /dev/tty,
	// so the probe below isn't enough — an interactive prompt on CI hangs.
	// CI=false is the `is-ci` escape hatch for developers who need to override
	// an inherited value.
	if v := os.Getenv("CI"); v != "" && v != "false" {
		return false
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return false
	}
	_ = tty.Close()
	return true
}

// IsTerminalWriter reports whether w is an *os.File backed by a terminal.
// Use for deciding on color, pager, progress bars, or other writer-scoped
// TTY formatting. For "can I prompt the user?" use CanPromptInteractively.
func IsTerminalWriter(w io.Writer) bool {
	f, ok := w.(*os.File)
	if !ok {
		return false
	}
	return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

package interactive

import (
	"bytes"
	"os"
	"testing"
)

func TestCanPromptInteractively_ForcedOn(t *testing.T) {
	t.Setenv("ENTIRE_FAKE_TTY", "1")
	if !CanPromptInteractively() {
		t.Error("CanPromptInteractively() = false; want true when ENTIRE_FAKE_TTY=1")
	}
}

func TestCanPromptInteractively_ForcedOff(t *testing.T) {
	t.Setenv("ENTIRE_FAKE_TTY", "0")
	if CanPromptInteractively() {
		t.Error("CanPromptInteractively() = true; want false when ENTIRE_FAKE_TTY=0")
	}
}

// Under `go test` without an explicit ENTIRE_FAKE_TTY override, testing.Testing()
// short-circuits to non-interactive.
func TestCanPromptInteractively_TestingDefaultsOff(t *testing.T) {
	t.Setenv("ENTIRE_FAKE_TTY", "")
	_ = os.Unsetenv("ENTIRE_FAKE_TTY")
	if CanPromptInteractively() {
		t.Error("CanPromptInteractively() = true; want false under testing.Testing()")
	}
}

func TestCanPromptInteractively_AgentEnvGuards(t *testing.T) {
	// ENTIRE_FAKE_TTY=1 bypasses testing.Testing() so we can exercise the
	// agent-env guards — they must still force non-interactive regardless.
	t.Setenv("ENTIRE_FAKE_TTY", "1")

	cases := []struct {
		name, key, val string
	}{
		{"gemini", "GEMINI_CLI", "1"},
		{"copilot", "COPILOT_CLI", "1"},
		{"pi", "PI_CODING_AGENT", "true"},
		{"git-terminal-prompt-off", "GIT_TERMINAL_PROMPT", "0"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			// ENTIRE_FAKE_TTY=1 wins by design; to test agent guards we must
			// clear the override and let testing.Testing() be bypassed by the
			// agent check coming next. Use empty override so the env precedence
			// check falls through to the agent guards.
			t.Setenv("ENTIRE_FAKE_TTY", "")
			_ = os.Unsetenv("ENTIRE_FAKE_TTY")
			t.Setenv(c.key, c.val)
			// testing.Testing() returns true here too, so this test only
			// asserts that the gate returns false (which both paths satisfy).
			if CanPromptInteractively() {
				t.Errorf("CanPromptInteractively() = true; want false when %s=%s", c.key, c.val)
			}
		})
	}
}

func TestCanPromptInteractively_CIEnv(t *testing.T) {
	t.Setenv("ENTIRE_FAKE_TTY", "")
	_ = os.Unsetenv("ENTIRE_FAKE_TTY")
	t.Setenv("CI", "true")
	if CanPromptInteractively() {
		t.Error("CanPromptInteractively() = true; want false when CI=true")
	}
}

// CI=false is the `is-ci` escape hatch: a dev may set it to override an
// inherited CI=true. Verify the CI branch doesn't short-circuit to false,
// using ENTIRE_FAKE_TTY=1 to stand in for a real TTY in the test host.
func TestCanPromptInteractively_CIFalseOverride(t *testing.T) {
	t.Setenv("CI", "false")
	t.Setenv("ENTIRE_FAKE_TTY", "1")
	if !CanPromptInteractively() {
		t.Error("CanPromptInteractively() = false; want true when CI=false")
	}
}

func TestIsTerminalWriter_NonFile(t *testing.T) {
	t.Parallel()
	if IsTerminalWriter(&bytes.Buffer{}) {
		t.Error("IsTerminalWriter(*bytes.Buffer) = true; want false")
	}
}

func TestIsTerminalWriter_Pipe(t *testing.T) {
	t.Parallel()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("os.Pipe: %v", err)
	}
	defer r.Close()
	defer w.Close()
	if IsTerminalWriter(w) {
		t.Error("IsTerminalWriter(pipe) = true; want false")
	}
}

